# canonical shape signatures under dihedral symmetries for 4-connected comps
from collections import defaultdict

def canon(cells):
 r0=min(x for x,y in cells); c0=min(y for x,y in cells)
 pts={(x-r0,y-c0) for x,y in cells}
 transforms=[]
 for flip in [False,True]:
  base={(x,-y if flip else y) for x,y in pts}
  for k in range(4):
   cur=base
   for _ in range(k): cur={(y,-x) for x,y in cur}
   a=min(x for x,y in cur); b=min(y for x,y in cur)
   norm=tuple(sorted((x-a,y-b) for x,y in cur))
   transforms.append(norm)
 return min(transforms)
